<?php $aq=db()->prepare('SELECT reference FROM sales_recurring_agreements WHERE contract_id=?');$aq->execute([$contract['id']]);$agreement=$aq->fetchColumn();if($agreement): ?><p><a href="<?= e(crm_url('recurring-agreement.php?id='.$contract['id'])) ?>">Υπογεγραμμένη συμφωνία: <?= e($agreement) ?></a></p><?php else: ?><p>Προϋπάρχουσα συμφωνία — δεν δημιουργήθηκε αναδρομικά δήλωση υπογραφής.</p><?php endif; ?><?php if($manager): ?><form class="stack" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="recurring_receipt"><input type="hidden" name="contract_id" value="<?= e($contract['id']) ?>"><label>Μήνας έναρξης της περιόδου<input name="period_month" type="month" required></label><label>Πραγματική είσπραξη (€)<input name="received_amount" type="number" min="0.01" step="0.01" required></label><label>Επιλέξιμο μέρος χωρίς ΦΠΑ/εξαιρούμενα (€)<input name="eligible_base_amount" type="number" min="0.01" step="0.01" required></label><label>Ημερομηνία είσπραξης<input name="received_at" type="date" max="<?= e(date('Y-m-d')) ?>" required></label><label>Μοναδική αναφορά / παραστατικό<input name="receipt_reference" required maxlength="255"></label><button class="button">Καταγραφή είσπραξης</button></form><?php if($contract['active']): ?><details><summary>Λήξη συμφωνίας</summary><form class="stack" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="close_recurring"><input type="hidden" name="contract_id" value="<?= e($contract['id']) ?>"><label>Αιτιολογία<textarea name="reason" required minlength="20" maxlength="3000"></textarea></label><button class="button">Διακοπή νέων προμηθειών — διατήρηση παλαιών</button></form></details><?php endif; ?><?php endif; ?></section><?php endforeach; ?>
<?php if($manager): ?><form method="post" enctype="multipart/form-data" class="card form-section stack"><?= csrf_field() ?><input type="hidden" name="action" value="create_recurring"><h2>Νέα επαναλαμβανόμενη συμφωνία</h2><p>Προηγείται έγγραφη συμφωνία ανά πελάτη, με συγκεκριμένο δικαιούχο, αντικείμενο, βάση/ποσοστό και διάρκεια. Οι παλιές συμφωνίες και οι αρχικές δόσεις δεν αλλάζουν αναδρομικά.</p><label>Πλήρες υπογεγραμμένο PDF<input type="file" name="agreement_pdf" accept="application/pdf" required></label><label>Αναφορά συμφωνίας<input name="agreement_reference" minlength="5" maxlength="200" required></label><label>Ημερομηνία υπογραφής<input name="signed_on" type="date" max="<?= e(date('Y-m-d')) ?>" required></label><label class="checkbox-row"><input type="checkbox" name="signed_confirmed" value="1" required> Έλεγξα την υπογραφή του Μελά, την αποδοχή του δικαιούχου και ότι οι όροι του αρχείου συμφωνούν με τα παρακάτω πεδία.</label><label>Ο κωδικός μου<input type="password" name="actor_password" required autocomplete="current-password"></label><label>Ήδη εγκεκριμένο αντικείμενο<select name="component_id"><?php foreach(db()->query("SELECT c.id,c.description,l.lead_reference FROM lead_service_components c JOIN sales_leads l ON l.id=c.lead_id WHERE c.policy_version<>'recurring-v26' ORDER BY c.approved_at DESC")->fetchAll() as $component): ?><option value="<?= e($component['id']) ?>"><?= e($component['lead_reference'].' · '.$component['description']) ?></option><?php endforeach; ?></select></label><label>Καθαρή επιλέξιμη βάση ολόκληρης περιόδου (€)<input name="period_base" type="number" min="0.01" step="0.01" required></label><label>Συχνότητα που ορίζει η υπογεγραμμένη συμφωνία<select name="interval_months"><option value="1">Κάθε μήνα</option><option value="2">Κάθε 2 μήνες</option><option value="3">Κάθε 3 μήνες</option><option value="6">Κάθε 6 μήνες</option><option value="12">Κάθε έτος</option></select></label><p>Η πρώτη περίοδος αρχίζει στον μήνα έναρξης της σύμβασης. Μερική είσπραξη καταχωρίζεται στην ίδια περίοδο, όχι σε νέο μήνα. Δεν γίνεται αυτόματη ανανέωση ή δημιουργία αμοιβής.</p><label>Έναρξη<input name="starts_on" type="date" required></label><label>Λήξη (προαιρετικά)<input name="ends_on" type="date"></label><label>Όροι, εξαιρούμενα ποσά και τεκμηρίωση<textarea name="note" required minlength="20" maxlength="3000"></textarea></label><button class="button">Έγκριση επαναλαμβανόμενης συμφωνίας</button></form><?php endif; ?>
